steps_json:
[
    {
        "title": "认清圆台",
        "description": "先把图形看成一个圆台：它有上底、下底和高，体积要围着这三个量来算。",
        "bubbleText": "先别急着算，先认清它是谁：上小下大，中间收起来的这个就是圆台。",
        "bubblePos": {
            "x": 28.0,
            "y": 228.0
        },
        "arrowTarget": {
            "x": 421.0,
            "y": 334.0
        }
    },
    {
        "title": "找出要素",
        "description": "圆台的两个底面是圆，且共用同一条中心轴；接下来只需要记住上底半径 $r$、下底半径 $R$ 和高 $h$。",
        "bubbleText": "你只要盯住三样：小圆半径、大圆半径、竖着的高。",
        "bubblePos": {
            "x": 32.0,
            "y": 228.0
        },
        "arrowTarget": {
            "x": 629.0,
            "y": 180.0
        }
    },
    {
        "title": "建立关系",
        "description": "圆台可以看成大圆锥减去小圆锥，两个圆锥有相同的顶点，底面半径分别对应 $R$ 和 $r$。",
        "bubbleText": "把它想成“切掉一截”的圆锥，很多公式就顺了。",
        "bubblePos": {
            "x": 28.0,
            "y": 228.0
        },
        "arrowTarget": {
            "x": 420.0,
            "y": 335.0
        }
    },
    {
        "title": "连接相似",
        "description": "因为截出来的两个圆锥相似，所以半径和高的比例保持一致，这一步是公式成立的关键。",
        "bubbleText": "相似图形最厉害的地方，就是“对应量按同样比例变”。",
        "bubblePos": {
            "x": 28.0,
            "y": 228.0
        },
        "arrowTarget": {
            "x": 420.0,
            "y": 218.0
        }
    },
    {
        "title": "写出公式",
        "description": "圆台体积公式是 $V=\\dfrac{\\pi h}{3}(R^2+Rr+r^2)$，它正好把大圆锥和小圆锥的关系合并好了。",
        "bubbleText": "这个式子不是硬背出来的，它是把“减去一个小圆锥”整理后的结果。",
        "bubblePos": {
            "x": 28.0,
            "y": 228.0
        },
        "arrowTarget": {
            "x": 429.0,
            "y": 120.0
        }
    },
    {
        "title": "代入计算",
        "description": "把题目给出的 $R$、$r$、$h$ 代入公式，先算括号，再乘 $\\pi h/3$，得到圆台体积。",
        "bubbleText": "算的时候按顺序来：先括号，后乘外面那一层。",
        "bubblePos": {
            "x": 28.0,
            "y": 228.0
        },
        "arrowTarget": {
            "x": 419.0,
            "y": 531.0
        }
    },
    {
        "title": "检查答案",
        "description": "最后检查结果是否为立方单位，并且数值应落在大圆锥体积与小圆锥体积之间，说明结果合理。",
        "bubbleText": "体积一定带立方单位，而且圆台的答案应该夹在两个圆锥之间。",
        "bubblePos": {
            "x": 28.0,
            "y": 228.0
        },
        "arrowTarget": {
            "x": 420.0,
            "y": 412.0
        }
    }
]
